const records = $input.all();

const seen = new Map();
const duplicates = [];

for (const item of records) {
  const cycleId = String(item.json.Cycle_ID || "").trim();

  if (!cycleId) {
    duplicates.push({
      json: {
        Issue_Type: "MISSING_CYCLE_ID",
        Task_ID: item.json.Task_ID || "",
        Employee: item.json.Assigned_To || "",
        Details: "Task record has no Cycle_ID"
      }
    });
    continue;
  }

  if (seen.has(cycleId)) {
    duplicates.push({
      json: {
        Issue_Type: "DUPLICATE_TASK_CYCLE",
        Cycle_ID: cycleId,
        Task_ID: item.json.Task_ID || "",
        Employee: item.json.Assigned_To || "",
        Details: "This Cycle_ID appears more than once"
      }
    });
  } else {
    seen.set(cycleId, true);
  }
}

return duplicates;

const records = $input.all();

const seen = new Set();
const issues = [];

for (const item of records) {
  const record = item.json;

  const completionId = String(
    record.Completion_ID || ""
  ).trim();

  const cycleId = String(
    record.Cycle_ID || ""
  ).trim();

  if (!completionId || !cycleId) {
    issues.push({
      json: {
        Issue_Type: "MISSING_COMPLETION_REFERENCE",
        Cycle_ID: cycleId,
        Details: "Completion_ID or Cycle_ID is missing"
      }
    });
    continue;
  }

  if (seen.has(cycleId)) {
    issues.push({
      json: {
        Issue_Type: "DUPLICATE_COMPLETION",
        Completion_ID: completionId,
        Cycle_ID: cycleId,
        Task_ID: record.Task_ID,
        Employee: record.Assigned_To,
        Details: "Multiple completion records exist for this cycle"
      }
    });
  } else {
    seen.add(cycleId);
  }
}

return issues;

const records = $input.all();

const seen = new Set();
const issues = [];

for (const item of records) {
  const alert = item.json;

  const alertId = String(alert.Alert_ID || "").trim();

  if (!alertId) {
    issues.push({
      json: {
        Issue_Type: "MISSING_ALERT_ID",
        Cycle_ID: alert.Cycle_ID || "",
        Details: "Escalation record has no Alert_ID"
      }
    });
    continue;
  }

  if (seen.has(alertId)) {
    issues.push({
      json: {
        Issue_Type: "DUPLICATE_ESCALATION_ALERT",
        Alert_ID: alertId,
        Cycle_ID: alert.Cycle_ID,
        Task_ID: alert.Task_ID,
        Employee: alert.Employee,
        Details: "This Alert_ID appears more than once"
      }
    });
  } else {
    seen.add(alertId);
  }
}

return issues;

const tasks = $("Read Task Cycles for Integrity Audit").all();

const issues = [];

for (const item of tasks) {
  const task = item.json;

  if (
    String(task.Status || "").trim().toLowerCase() !== "completed"
  ) {
    continue;
  }

  const taskId = String(task.Task_ID || "").trim();

  if (taskId === "TSK001") {
    if (!String(task.Completion_Proof || "").trim()) {
      issues.push({
        json: {
          Issue_Type: "MISSING_COMPLETION_PROOF",
          Cycle_ID: task.Cycle_ID,
          Task_ID: taskId,
          Employee: task.Assigned_To,
          Details: "Daily WhatsApp completion proof is missing"
        }
      });
    }
  } else if (
    !String(task.Ticket_ID || "").trim()
  ) {
    issues.push({
      json: {
        Issue_Type: "MISSING_TICKET_ID",
        Cycle_ID: task.Cycle_ID,
        Task_ID: taskId,
        Employee: task.Assigned_To,
        Details: "Completed portal task has no Ticket ID"
      }
    });
  }
}

return issues;

const cycles = $("Read Task Cycles for Integrity Audit").all();
const completions = $("Read Completion Records for Audit").all();
const alerts = $("Read Escalation Records for Audit").all();

const cycleIds = cycles
  .map(x => String(x.json.Cycle_ID || "").trim())
  .filter(Boolean);

const completionIds = completions
  .map(x => String(x.json.Cycle_ID || "").trim())
  .filter(Boolean);

const alertIds = alerts
  .map(x => String(x.json.Alert_ID || "").trim())
  .filter(Boolean);

const countDuplicates = values =>
  values.length - new Set(values).size;

return [{
  json: {
    Audit_Date: new Date().toISOString(),
    Task_Cycle_Records: cycles.length,
    Duplicate_Task_Cycles: countDuplicates(cycleIds),
    Completion_Records: completions.length,
    Duplicate_Completions: countDuplicates(completionIds),
    Escalation_Records: alerts.length,
    Duplicate_Escalation_Alerts: countDuplicates(alertIds),
    Acknowledged_Alerts: alerts.filter(
      x => String(x.json.Manager_Acknowledged).toLowerCase() === "true"
    ).length,
    Leadership_Escalated_Alerts: alerts.filter(
      x => String(x.json.Leadership_Escalated).toLowerCase() === "true"
    ).length,
    Audit_Result: "COMPLETED"
  }
}];
